/**
 * Session stream utility functions.
 *
 * Parses raw session events from events.jsonl into structured display blocks.
 *
 * AC: @ui-session-stream ac-1 — Structured event blocks
 */

import type { SessionEvent } from '$lib/api';

export type BlockType = 'message' | 'tool_call' | 'tool_result' | 'thinking' | 'system';

export interface MessageBlock {
	type: 'message';
	content: string;
	timestamp: number;
	seq: number;
}

export interface ToolCallBlock {
	type: 'tool_call';
	toolName: string;
	toolCallId: string;
	input: unknown;
	output?: unknown;
	status: 'pending' | 'running' | 'completed' | 'failed';
	startedAt: number;
	completedAt?: number;
	durationMs?: number;
	seq: number;
}

export interface ThinkingBlock {
	type: 'thinking';
	content: string;
	timestamp: number;
	seq: number;
}

export interface SystemBlock {
	type: 'system';
	label: string;
	detail?: string;
	timestamp: number;
	seq: number;
}

export type DisplayBlock = MessageBlock | ToolCallBlock | ThinkingBlock | SystemBlock;

/**
 * Tool name to icon mapping.
 */
const TOOL_ICONS: Record<string, string> = {
	Read: '\u{1F4C4}',
	Write: '\u{270F}\u{FE0F}',
	Edit: '\u{270F}\u{FE0F}',
	Bash: '$',
	Grep: '\u{1F50D}',
	Glob: '\u{1F4C1}',
	WebFetch: '\u{1F310}',
	WebSearch: '\u{1F310}',
	Task: '\u{1F916}',
	TodoWrite: '\u{2705}',
	NotebookEdit: '\u{1F4D3}',
};

export function getToolIcon(toolName: string): string {
	return TOOL_ICONS[toolName] ?? '\u{1F527}';
}

/**
 * Extract a short preview of tool input for collapsed display.
 */
