	if (str.length <= max) return str;
	return str.slice(0, max) + '\u2026';
}

/**
 * Parse raw session events into structured display blocks.
 *
 * AC: @ui-session-stream ac-1
 */
export function parseEventsToBlocks(events: SessionEvent[]): DisplayBlock[] {
	const blocks: DisplayBlock[] = [];
	const toolCalls = new Map<string, ToolCallBlock>();

	for (const event of events) {
		const data = event.data as Record<string, unknown> | null;
		if (!data) continue;

		switch (event.type) {
			case 'session.start': {
				blocks.push({
					type: 'system',
					label: 'Session started',
					detail: data.agent_type ? `Agent: ${data.agent_type}` : undefined,
					timestamp: event.ts,
					seq: event.seq,
				});
				break;
			}

			case 'session.end':
			case 'session.wrapup': {
				blocks.push({
					type: 'system',
					label: event.type === 'session.end' ? 'Session ended' : 'Session wrapping up',
					detail: data.reason ? String(data.reason) : undefined,
					timestamp: event.ts,
					seq: event.seq,
				});
				break;
			}

			case 'session.update': {
				const update = data.update as Record<string, unknown> | undefined;
				if (!update) break;

				const sessionUpdate = update.sessionUpdate as string | undefined;

				if (sessionUpdate === 'assistant_text' || sessionUpdate === 'assistant') {
					const content = (update.text ?? update.content ?? '') as string;
					if (content) {
						// Merge consecutive message blocks
						const lastBlock = blocks[blocks.length - 1];
						if (lastBlock?.type === 'message') {
							lastBlock.content += content;
						} else {
							blocks.push({
								type: 'message',
								content,
								timestamp: event.ts,
								seq: event.seq,
							});
						}
					}
				} else if (sessionUpdate === 'thinking' || sessionUpdate === 'assistant_thinking') {
					const content = (update.text ?? update.content ?? '') as string;
					if (content) {
						const lastBlock = blocks[blocks.length - 1];
						if (lastBlock?.type === 'thinking') {
							lastBlock.content += content;
						} else {
							blocks.push({
								type: 'thinking',
								content,
								timestamp: event.ts,
								seq: event.seq,
							});
						}
					}
				} else if (sessionUpdate === 'tool_call') {
					const toolCallId = (update.toolCallId ?? update.tool_call_id ?? update.id ?? '') as string;
					const toolName = (update.tool ?? update.toolName ?? update.name ?? 'unknown') as string;
					const rawInput = update.rawInput ?? update.input;

					const block: ToolCallBlock = {
						type: 'tool_call',
						toolName,
						toolCallId,
						input: rawInput,
						status: 'running',
						startedAt: event.ts,
						seq: event.seq,
					};

					toolCalls.set(toolCallId, block);
					blocks.push(block);
				} else if (sessionUpdate === 'tool_result') {
					const toolCallId = (update.toolCallId ?? update.tool_call_id ?? update.id ?? '') as string;
					const existing = toolCalls.get(toolCallId);

					if (existing) {
						existing.output = update.output ?? update.rawOutput ?? update.content;
						existing.status = (update.error || update.isError) ? 'failed' : 'completed';
						existing.completedAt = event.ts;
						existing.durationMs = event.ts - existing.startedAt;
					}
				}
				break;
			}

			case 'tool.call': {
				const toolName = (data.tool ?? data.name ?? 'unknown') as string;
				const toolCallId = (data.toolCallId ?? data.tool_call_id ?? data.id ?? `tool-${event.seq}`) as string;

				const block: ToolCallBlock = {
					type: 'tool_call',
					toolName,
					toolCallId,
					input: data.input ?? data.rawInput ?? data.args,
					status: 'running',
					startedAt: event.ts,
					seq: event.seq,
				};

				toolCalls.set(toolCallId, block);
				blocks.push(block);
				break;
			}

			case 'tool.result': {
				const toolCallId = (data.toolCallId ?? data.tool_call_id ?? data.id ?? '') as string;
				const existing = toolCalls.get(toolCallId);

				if (existing) {
					existing.output = data.output ?? data.rawOutput ?? data.content;
					existing.status = (data.error || data.isError) ? 'failed' : 'completed';
					existing.completedAt = event.ts;
					existing.durationMs = event.ts - existing.startedAt;
				}
