		if (!WRITE_TOOLS.has(block.toolName)) continue;
		const input = block.input as Record<string, unknown> | null;
		if (!input) continue;
		const filePath = (input.file_path ?? input.notebook_path) as string | undefined;
		if (filePath) files.add(filePath);
	}
	return [...files].sort();
}

