        isStreaming: false,
      });

      // JavaScript code should be rendered
      await expect.poll(() => container.textContent).toContain('const x = 1');
      // Both code blocks should be present (one for JS, one for mermaid)
      await expect.poll(() => container.querySelectorAll('.code-block, pre').length).toBe(2);
    });
  });

  describe('edge cases', () => {
    it('handles empty content', async () => {
      const { container } = render(StreamingMarkdown, {
        content: '',
        isStreaming: false,
      });

      // Should render without errors
      await expect.poll(() => container.querySelector('.streaming-markdown')).not.toBeNull();
    });

    it('handles whitespace-only content', async () => {
      const { container } = render(StreamingMarkdown, {
