	if (hours > 0) return `${hours}h ${mins % 60}m`;
	if (mins > 0) return `${mins}m ${secs % 60}s`;
	return `${secs}s`;
}

/**
 * Format a timestamp to a time string.
 */
export function formatTime(ts: number): string {
