    13→ */
    14→export async function loadMermaid() {
    15→  if (!mermaidPromise) {
    16→    mermaidPromise = import('mermaid').then((m) => {
    17→      m.default.initialize({
    18→        startOnLoad: false,
    19→        theme: 'dark',
    20→        securityLevel: 'strict',
    21→        // Suppress console logs from mermaid
    22→        logLevel: 'error' as const,
    23→      });
    24→      return m;
    25→    });
    26→  }
    27→  return mermaidPromise;
    28→}
    29→
    30→/** Counter for unique diagram IDs */
    31→let diagramCounter = 0;
    32→
    33→/**
    34→ * Render a mermaid diagram into an element.
    35→ *
    36→ * @param element - The container element to render into
    37→ * @param code - The mermaid diagram code
    38→ * @throws Error if rendering fails (invalid syntax, etc.)
    39→ */
    40→export async function renderMermaid(element: HTMLElement, code: string): Promise<void> {
    41→  const mermaid = await loadMermaid();
    42→
    43→  // Generate unique ID for this diagram
    44→  const id = `mermaid-${Date.now()}-${diagramCounter++}`;
    45→
    46→  const { svg } = await mermaid.default.render(id, code);
    47→  element.innerHTML = svg;
    48→}
    49→
    50→/**
    51→ * Check if a language identifier indicates a mermaid diagram.
    52→ */
    53→export function isMermaidLanguage(language: string | undefined): boolean {
    54→  return language?.toLowerCase() === 'mermaid';
    55→}
