    72→  daemon: async ({}, use) => {
    73→    // Check Bun is available (daemon requires it)
    74→    if (!(await checkBunAvailable())) {
    75→      throw new Error(
    76→        'Bun runtime required for daemon. Install: curl -fsSL https://bun.sh/install | bash'
    77→      );
    78→    }
    79→
    80→    // Clean up any existing daemon
    81→    await cleanupExistingDaemon();
    82→
    83→    // Create temp directory with .kspec subdirectory
    84→    const tempDir = join(tmpdir(), 'kspec-e2e-' + Date.now());
    85→    const kspecDir = join(tempDir, '.kspec');
    86→    mkdirSync(kspecDir, { recursive: true });
    87→
    88→    // Copy E2E test fixtures to .kspec subdirectory (simulating shadow worktree mode)
    89→    if (existsSync(E2E_FIXTURES)) {
    90→      cpSync(E2E_FIXTURES, kspecDir, {
    91→        recursive: true,
    92→        filter: (src) => !src.includes('test-base') && !src.includes('project-tests')
    93→      });
    94→    } else {
    95→      throw new Error(`E2E test fixtures not found at ${E2E_FIXTURES}`);
    96→    }
    97→
    98→    // Copy project-level tests directory for AC coverage scanning
    99→    const projectTests = join(E2E_FIXTURES, 'project-tests');
   100→    if (existsSync(projectTests)) {
   101→      cpSync(projectTests, join(tempDir, 'tests'), { recursive: true });
   102→    }
   103→
   104→    // Initialize git repo in project root (required for kspec)
   105→    execSync('git init', { cwd: tempDir, stdio: 'ignore' });
   106→    execSync('git config user.email "test@test.com"', { cwd: tempDir, stdio: 'ignore' });
   107→    execSync('git config user.name "Test"', { cwd: tempDir, stdio: 'ignore' });
   108→
   109→    // Set up shadow worktree simulation for kspec to detect .kspec/ as spec directory
   110→    // The shadow detection checks if .kspec/.git is a file starting with "gitdir:"
   111→    // We create a fake .git file that satisfies this check
   112→    const gitWorktreesDir = join(tempDir, '.git', 'worktrees', '-kspec');
   113→    mkdirSync(gitWorktreesDir, { recursive: true });
   114→    // Create the .git file in .kspec pointing to the worktree location
   115→    writeFileSync(join(kspecDir, '.git'), `gitdir: ${gitWorktreesDir}\n`);
   116→    // Create minimal worktree metadata so git doesn't complain
   117→    writeFileSync(join(gitWorktreesDir, 'gitdir'), `${join(tempDir, '.git')}\n`);
   118→    writeFileSync(join(gitWorktreesDir, 'HEAD'), 'ref: refs/heads/kspec-meta\n');
   119→
   120→    // Verify web UI is built (daemon serves it for E2E tests)
   121→    if (!existsSync(WEB_UI_BUILD)) {
   122→      throw new Error(
   123→        `Web UI not built. Run 'npm run build -w packages/web-ui' first.\n` +
   124→        `Expected build at: ${WEB_UI_BUILD}`
   125→      );
   126→    }
   127→
   128→    // Start daemon - pass project root (tempDir), daemon derives .kspec internally
   129→    // Set WEB_UI_DIR so daemon serves the built web UI
   130→    const startResult = spawnSync(
   131→      'kspec',
   132→      ['serve', 'start', '--daemon', '--port', String(DAEMON_PORT), '--kspec-dir', tempDir],
   133→      {
   134→        cwd: tempDir,
   135→        encoding: 'utf-8',
   136→        env: { ...process.env, WEB_UI_DIR: WEB_UI_BUILD }
   137→      }
   138→    );
   139→
   140→    if (startResult.status !== 0) {
   141→      throw new Error('Failed to start daemon: ' + startResult.stderr);
   142→    }
   143→
   144→    // Wait for daemon to be ready by polling health endpoint
   145→    const maxAttempts = 30;
   146→    const pollInterval = 100;
   147→    for (let i = 0; i < maxAttempts; i++) {
   148→      try {
   149→        const response = await fetch(`http://localhost:${DAEMON_PORT}/api/health`);
   150→        if (response.ok) break;
   151→      } catch {
   152→        // Daemon not ready yet
   153→      }
   154→      if (i === maxAttempts - 1) {
   155→        throw new Error(`Daemon failed to become ready after ${maxAttempts * pollInterval}ms`);
   156→      }
   157→      await new Promise((r) => setTimeout(r, pollInterval));
   158→    }
   159→
   160→    // Helper to create a valid second project for multi-project tests
   161→    // AC: @multi-directory-daemon ac-25 - Tests need multiple valid projects
   162→    async function createSecondProject(): Promise<string> {
   163→      const secondProjectPath = tempDir + '-second';
   164→      const secondKspecDir = join(secondProjectPath, '.kspec');
   165→
   166→      // Create project directory with valid .kspec structure
   167→      mkdirSync(secondKspecDir, { recursive: true });
   168→
   169→      // Create minimal kynetic.yaml
   170→      writeFileSync(
   171→        join(secondKspecDir, 'kynetic.yaml'),
   172→        `kynetic: "1.0"
   173→project: Second Test Project
   174→`
   175→      );
   176→
   177→      // Create project.tasks.yaml (empty tasks file)
   178→      writeFileSync(
   179→        join(secondKspecDir, 'project.tasks.yaml'),
   180→        `# Tasks for second test project
   181→tasks: []
   182→`
   183→      );
   184→
   185→      // Initialize git repo in second project
   186→      execSync('git init', { cwd: secondProjectPath, stdio: 'ignore' });
   187→      execSync('git config user.email "test@test.com"', { cwd: secondProjectPath, stdio: 'ignore' });
   188→      execSync('git config user.name "Test"', { cwd: secondProjectPath, stdio: 'ignore' });
   189→
   190→      // Set up shadow worktree simulation (same as main project)
   191→      const gitWorktreesDir = join(secondProjectPath, '.git', 'worktrees', '-kspec');
   192→      mkdirSync(gitWorktreesDir, { recursive: true });
   193→      writeFileSync(join(secondKspecDir, '.git'), `gitdir: ${gitWorktreesDir}\n`);
   194→      writeFileSync(join(gitWorktreesDir, 'gitdir'), `${join(secondProjectPath, '.git')}\n`);
   195→      writeFileSync(join(gitWorktreesDir, 'HEAD'), 'ref: refs/heads/kspec-meta\n');
   196→
   197→      // Register second project with daemon
   198→      const response = await fetch(`http://localhost:${DAEMON_PORT}/api/projects`, {
   199→        method: 'POST',
   200→        headers: { 'Content-Type': 'application/json' },
   201→        body: JSON.stringify({ path: secondProjectPath }),
   202→      });
   203→
   204→      if (!response.ok) {
   205→        const error = await response.text();
   206→        throw new Error(`Failed to register second project: ${error}`);
   207→      }
   208→
   209→      return secondProjectPath;
   210→    }
   211→
   212→    // Provide fixture to test
   213→    await use({ tempDir, kspecDir, createSecondProject });
   214→
   215→    // Cleanup: stop daemon - pass project root to match start
   216→    spawnSync('kspec', ['serve', 'stop', '--kspec-dir', tempDir], {
   217→      cwd: tempDir,
   218→      encoding: 'utf-8',
   219→    });
   220→    await new Promise((r) => setTimeout(r, 1000));
   221→
   222→    // Remove temp directories (main and any second project)
   223→    try {
   224→      rmSync(tempDir, { recursive: true, force: true });
   225→      // Also clean up second project if it exists
   226→      rmSync(tempDir + '-second', { recursive: true, force: true });
   227→    } catch {
   228→      // Best effort cleanup
   229→    }
   230→  },
   231→});
   232→
   233→export { expect };
