 23→	let scrollContainer: HTMLDivElement | undefined = $state();
 24→	let shouldAutoScroll = $state(true);
 25→	let userScrolling = $state(false);
 26→	let scrollDebounceTimer: ReturnType<typeof setTimeout> | undefined;
 27→
 28→	// AC: @ui-session-stream ac-3 — Pause auto-scroll when user scrolls up
 29→	function handleScroll() {
 30→		if (!scrollContainer) return;
 31→
 32→		const { scrollHeight, scrollTop, clientHeight } = scrollContainer;
 33→		const distanceFromBottom = scrollHeight - scrollTop - clientHeight;
 34→
 35→		// Clear existing debounce
 36→		if (scrollDebounceTimer) clearTimeout(scrollDebounceTimer);
 37→		userScrolling = true;
 38→
 39→		scrollDebounceTimer = setTimeout(() => {
 40→			userScrolling = false;
 41→		}, 150);
 42→
 43→		// AC: @ui-session-stream ac-3 — 100px threshold for re-enabling auto-scroll
 44→		shouldAutoScroll = distanceFromBottom < 100;
 45→	}
 46→
 47→	// AC: @ui-session-stream ac-3 — Auto-scroll to follow new content
 48→	$effect(() => {
 49→		// Track block count and streaming text to trigger scroll
 50→		const _blockCount = blocks.length;
 51→		const _text = streamingText;
 52→
 53→		if (shouldAutoScroll && !userScrolling && scrollContainer) {
 54→			requestAnimationFrame(() => {
 55→				if (scrollContainer) {
 56→					scrollContainer.scrollTo({
 57→						top: scrollContainer.scrollHeight,
 58→						behavior: 'auto',
 59→					});
 60→				}
 61→			});
 62→		}
 63→	});
 64→
 65→	function jumpToBottom() {
 66→		shouldAutoScroll = true;
 67→		if (scrollContainer) {
 68→			scrollContainer.scrollTo({
 69→				top: scrollContainer.scrollHeight,
 70→				behavior: 'smooth',
 71→			});
 72→		}
 73→	}
 74→
 75→	let showJumpButton = $derived(!shouldAutoScroll && (isLive || blocks.length > 0));
 76→</script>
