  SESSION_COMPONENTS,
  "SessionContextPanel.svelte",
);
const SKELETON_PATH = join(
  SESSION_COMPONENTS,
  "SessionStreamSkeleton.svelte",
);
const SESSION_PAGE_PATH = join(
  WEB_UI_SRC,
  "routes",
  "sessions",
  "[id]",
  "+page.svelte",
);
